# Look at ggVennDiagram source
fns <- ls("package:ggVennDiagram")
for (fn in fns) {
  obj <- get(fn, envir = asNamespace("ggVennDiagram"))
  if (is.function(obj)) {
    args <- tryCatch(formals(obj), error = function(e) NULL)
    if (!is.null(args) && any(grepl("Venn|sets|overlap|region", paste(args), ignore.case = TRUE))) {
      cat("\n", fn, ": ", paste(names(args), collapse = ", "), "\n", sep = "")
    }
  }
}

